-- Features agreed at the client review meeting (30 Sep 2026):
--   * container, seal, trailer and LPO details on shipments, so the delivery
--     note can be generated by the system instead of uploaded by hand;
--   * the customer's LPO on the transport request and the invoice, so finance
--     never retypes it;
--   * scheduled report emails to finance, management and fleet;
--   * the maintenance warning 15 days before a service, as presented.
-- Safe to run more than once.

ALTER TABLE shipments
    ADD COLUMN IF NOT EXISTS container_no VARCHAR(40) NULL AFTER special_instructions,
    ADD COLUMN IF NOT EXISTS container_size VARCHAR(20) NULL AFTER container_no,
    ADD COLUMN IF NOT EXISTS seal_no VARCHAR(60) NULL AFTER container_size,
    ADD COLUMN IF NOT EXISTS trailer_plate VARCHAR(32) NULL AFTER seal_no,
    ADD COLUMN IF NOT EXISTS bill_of_lading VARCHAR(60) NULL AFTER trailer_plate,
    ADD COLUMN IF NOT EXISTS customer_reference VARCHAR(60) NULL AFTER bill_of_lading,
    ADD INDEX IF NOT EXISTS idx_shipment_container (container_no);

ALTER TABLE transport_requests
    ADD COLUMN IF NOT EXISTS lpo_number VARCHAR(60) NULL AFTER requested_by_contact,
    ADD COLUMN IF NOT EXISTS lpo_file VARCHAR(255) NULL AFTER lpo_number;

ALTER TABLE invoices
    ADD COLUMN IF NOT EXISTS lpo_number VARCHAR(60) NULL AFTER trip_id;

-- Payments and invoices already carry a currency column; make sure every old
-- payment matches the invoice it settles.
UPDATE payments p INNER JOIN invoices i ON i.id = p.invoice_id
   SET p.currency = i.currency
 WHERE p.currency <> i.currency;

CREATE TABLE IF NOT EXISTS report_subscriptions (
    id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
    report_key VARCHAR(60) NOT NULL,
    frequency ENUM('daily', 'weekly', 'monthly') NOT NULL DEFAULT 'weekly',
    recipients TEXT NULL,
    to_finance TINYINT(1) NOT NULL DEFAULT 0,
    to_management TINYINT(1) NOT NULL DEFAULT 0,
    to_fleet TINYINT(1) NOT NULL DEFAULT 0,
    to_logistics TINYINT(1) NOT NULL DEFAULT 0,
    to_warehouse TINYINT(1) NOT NULL DEFAULT 0,
    to_admin TINYINT(1) NOT NULL DEFAULT 0,
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    last_sent_at DATETIME NULL,
    last_status VARCHAR(255) NULL,
    notes TEXT NULL,
    deleted_at DATETIME NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    KEY idx_report_sub_active (is_active, deleted_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO permissions (permission_key, permission_label, permission_group, sort_order) VALUES
    ('report_emails', 'Report emails', 'Insights', 195)
ON DUPLICATE KEY UPDATE permission_label = VALUES(permission_label), permission_group = VALUES(permission_group);

-- Administrators and finance run the schedules; management can see them.
INSERT INTO role_permissions (role_id, permission_key, can_view, can_create, can_edit, can_delete, can_approve)
SELECT r.id, 'report_emails', 1, 1, 1, 1, 1 FROM roles r WHERE r.role_key IN ('super_admin', 'finance')
ON DUPLICATE KEY UPDATE can_view = 1, can_create = 1, can_edit = 1, can_delete = 1, can_approve = 1;

INSERT INTO role_permissions (role_id, permission_key, can_view, can_create, can_edit, can_delete, can_approve)
SELECT r.id, 'report_emails', 1, 0, 0, 0, 0 FROM roles r WHERE r.role_key IN ('management', 'logistics_manager', 'fleet_manager')
ON DUPLICATE KEY UPDATE can_view = 1;

-- The three schedules the meeting asked for, switched on, so they start the
-- morning after this is installed. Edit or switch them off under Reports → Report emails.
INSERT INTO report_subscriptions (report_key, frequency, to_finance, to_management, to_fleet, is_active, notes)
SELECT 'trip_profitability', 'weekly', 1, 1, 0, 1, 'Agreed at the client meeting, 30 Sep 2026.'
 WHERE NOT EXISTS (SELECT 1 FROM report_subscriptions WHERE report_key = 'trip_profitability' AND frequency = 'weekly');
INSERT INTO report_subscriptions (report_key, frequency, to_finance, to_management, to_fleet, is_active, notes)
SELECT 'fuel_consumption', 'daily', 0, 0, 1, 1, 'Agreed at the client meeting, 30 Sep 2026.'
 WHERE NOT EXISTS (SELECT 1 FROM report_subscriptions WHERE report_key = 'fuel_consumption' AND frequency = 'daily');
INSERT INTO report_subscriptions (report_key, frequency, to_finance, to_management, to_fleet, is_active, notes)
SELECT 'expense_summary', 'monthly', 1, 1, 0, 1, 'Agreed at the client meeting, 30 Sep 2026.'
 WHERE NOT EXISTS (SELECT 1 FROM report_subscriptions WHERE report_key = 'expense_summary' AND frequency = 'monthly');

-- The presentation promised a maintenance warning 15 days ahead.
UPDATE company_settings SET setting_value = '15' WHERE setting_key = 'service_alert_days' AND setting_value = '14';
